    }
    for(int i=N-1;i>=0;i--){
        if(S[i]=='2') R2[i]=(i+1<N?R2[i+1]:0)+1; else R2[i]=0;
    }
}

int max_substring(int N,char *S,int *L1,int *R2){
    int best=0;
    for(int i=0;i<N;i++){
        if(S[i]!='/') continue;
        int l = (i>0? L1[i-1]:0);
        int r = (i+1<N? R2[i+1]:0);
        int k = l<r?l:r;
        int len = 2*k+1;
        if(len>best) best=len;
    }
    return best;
}

